{'code': "from qgis.PyQt.QtWidgets import QAction, QMenu
mw = iface.mainWindow()
vm = mw.findChild(QMenu, 'mVectorMenu')
res = {}
for a in vm.actions():
    if a.menu() is not None:
        sub = a.menu()
        sub.aboutToShow.emit()
        acts = [x for x in sub.actions() if not x.isSeparator()]
        disabled = [x.text().replace('&','') for x in acts if not x.isEnabled()]
        res[a.text().replace('&','')] = {'submenu_obj': sub.objectName(), 'enabled': a.isEnabled(), 'count': len(acts), 'disabled': disabled}
result = res"}
